class Solution {
    combinationSum(candidates, target) {
        candidates.sort((a,b)=>a-b);
        const ans=[], path=[];
        const dfs=(start,remain)=>{
            if(remain===0){ ans.push([...path]); return; }
            for(let i=start;i<candidates.length && candidates[i]<=remain;i++){
                path.push(candidates[i]); dfs(i,remain-candidates[i]); path.pop();
            }
        };
        dfs(0,target); return ans;
    }
}

